      <div class="province-quota-control"><q-icon name="dataset" /><span>地区清单定额</span><select v-model="form.province" aria-label="选择清单定额省份" :disabled="analyzing" @change="handleProvinceChange"><option v-for="province in provinceOptions" :key="province" :value="province">{{ province }}{{ province === '山东省' ? '' : '（待补充）' }}</option></select><strong :class="{ pending: form.province !== '山东省' }">{{ form.province === '山东省' ? '山东省清单定额 · 已配置' : `${form.province}清单定额 · 待补充` }}</strong></div>
    </section>
