      <div class="progress-copy"><div><q-icon name="manage_search" /><strong>{{ progress.stage }}</strong><span>{{ progress.detail }}</span></div><b>{{ progress.percent }}%</b></div>
      <div class="progress-track"><i :style="{ width: `${progress.percent}%` }"></i></div>
      <div class="progress-steps"><span v-for="step in progressSteps" :key="step.label" :class="{ done: progress.percent >= step.at, active: progress.stage === step.label }"><q-icon :name="progress.percent >= step.at ? 'check_circle' : 'radio_button_unchecked'" />{{ step.label }}</span></div>
    </section>
    <div class="cost-layout">
      <aside class="tech-panel upload-panel">
        <div class="panel-heading"><h2 class="panel-title"><q-icon name="fact_check" />工程量清单</h2><span v-if="result" class="panel-meta">{{ result.items.length }} 项</span></div>
        <label class="upload-zone" :class="{ ready: selectedFile }"><q-icon :name="selectedFile ? 'task_alt' : 'file_upload'" size="30px" /><strong>{{ selectedFile?.name || '上传 Excel / PDF 清单' }}</strong><span>{{ selectedFile ? formatBytes(selectedFile.size) : 'xlsx、xlsm、csv、pdf，单文件不超过10MB' }}</span><input type="file" accept=".xlsx,.xlsm,.csv,.pdf" @change="selectFile"></label>
        <p v-if="errorMessage" class="error-message">{{ errorMessage }}</p>
        <div v-if="result" class="source-note"><strong>{{ result.source }}</strong><span>清单库 {{ result.catalog.lists }} 条 · 定额库 {{ result.catalog.quotas }} 条</span><span>{{ result.ai.mode }} · AI调用 {{ result.ai.calls }} 次<span v-if="result.ai.failures"> · 失败 {{ result.ai.failures }} 次</span></span><small>{{ result.limitations }}</small></div>
        <div v-if="result?.parsing.warnings.length" class="parse-warnings"><span v-for="warning in result.parsing.warnings" :key="warning">{{ warning }}</span></div>
        <div class="mini-summary"><article><span>匹配通过</span><strong>{{ result?.summary.matched ?? 0 }}</strong></article><article><span>待人工复核</span><strong class="warning">{{ result?.summary.review ?? 0 }}</strong></article></div>
      </aside>
      <main class="cost-main">
        <section class="tech-panel result-panel">
          <div class="panel-heading"><h2 class="panel-title"><q-icon name="calculate" />成本测算结果</h2><button v-if="result" class="text-action" :disabled="exporting" @click="exportReport">{{ exporting ? '正在生成报表…' : '导出测算明细' }}</button></div>
          <div class="quote-grid">
            <article class="total-card"><span>测算总成本</span><strong>{{ money(result?.summary.total) }}<small> 元</small></strong><em>人材机＋管理费＋利润＋税金</em></article>
            <article class="quote-card cyan"><span>保本成本价</span><strong>{{ money(result?.quotes.breakEven) }}<small> 元</small></strong><em>成本红线</em></article>
            <article class="quote-card blue"><span>常规报价</span><strong>{{ money(result?.quotes.regular) }}<small> 元</small></strong><em>当前按成本上浮5%</em></article>
            <article class="quote-card bright"><span>低价竞标价</span><strong>{{ money(result?.quotes.competitive) }}<small> 元</small></strong><em>当前按成本上浮2%</em></article>
          </div>
          <div class="breakdown"><article v-for="item in breakdown" :key="item.key"><span>{{ item.label }}</span><strong>{{ money(result?.summary[item.key]) }}</strong><small>元</small></article></div>
        </section>
