    </section>
    <section class="tech-panel detail-panel">
      <div class="panel-heading"><h2 class="panel-title"><q-icon name="table_view" />清单与定额匹配明细</h2><span class="panel-meta">点击项目查看详情并修改</span></div>
      <div class="table-wrap"><table><thead><tr><th>序号</th><th>项目名称</th><th>工程量</th><th>匹配清单</th><th>匹配定额</th><th>置信度</th><th>状态</th><th>操作</th></tr></thead><tbody>
