          <label><span>状态</span><select v-model="editItem.status"><option>已匹配</option><option>待复核</option></select></label><label class="readonly-field"><span>匹配方式（不可修改）</span><input :value="editItem.matchMethod" readonly></label>
          <label class="wide readonly-field"><span>AI匹配说明</span><textarea :value="editItem.aiReason" rows="3" readonly></textarea></label>
          <label class="wide readonly-field"><span>复核原因（系统判断，不可修改）</span><textarea :value="editReviewReasons" rows="3" readonly></textarea></label>
        </div>
        <p v-if="editError" class="edit-error">{{ editError }}</p>
