        <div class="catalog-search"><q-icon name="search" /><input v-model="listSearch" autofocus placeholder="输入清单编码或名称"><button type="button" @click="listSearch=''">清除</button></div>
        <div class="catalog-table"><table><thead><tr><th>选择</th><th>编码</th><th>名称</th><th>单位</th></tr></thead><tbody><tr v-for="entry in filteredLists" :key="entry.code" :class="{selected:listPickerCode===entry.code}" @click="listPickerCode=entry.code" @dblclick="confirmListPicker"><td><input v-model="listPickerCode" type="radio" :value="entry.code"></td><td>{{ entry.code }}</td><td>{{ entry.name }}</td><td>{{ entry.unit || '—' }}</td></tr></tbody></table></div>
