        <div class="catalog-search"><q-icon name="search" /><input v-model="quotaSearch" autofocus placeholder="输入定额编号、名称或章节"><button type="button" @click="quotaSearch=''">清除</button></div>
        <div class="quota-picker-body"><div class="picker-table"><h3>候选定额 <small>{{ filteredQuotas.length }} 条</small></h3><select v-model="quotaCandidateCodes" multiple size="16" @dblclick="addPickerQuotas"><option v-for="entry in filteredQuotas" :key="entry.code" :value="entry.code">{{ entry.code }}｜{{ entry.name }}｜{{ entry.unit || '无单位' }}｜{{ money(entry.unitLabour+entry.unitMaterial+entry.unitMachine) }}元</option></select></div><div class="quota-picker-actions"><button type="button" class="primary" @click="addPickerQuotas">添加 →</button><button type="button" class="secondary" :disabled="!quotaRemoveCodes.length" @click="removePickerQuotas">← 移除</button></div><div class="picker-table selected-quota-panel"><h3>已选定额 <small>{{ quotaPickerSelections.length }} 条</small></h3><div v-if="quotaPickerSelections.length" class="selected-quota-list"><button v-for="entry in quotaPickerSelections" :key="entry.code" type="button" :class="{ selected: quotaRemoveCodes.includes(entry.code) }" @click="toggleQuotaRemoval(entry.code)"><span class="selected-quota-code">{{ entry.code }}</span><strong>{{ entry.name }}</strong><small>{{ entry.chapter || '定额库' }} · {{ entry.unit || '无单位' }}</small><q-icon :name="quotaRemoveCodes.includes(entry.code) ? 'check_circle' : 'radio_button_unchecked'" /></button></div><div v-else class="selected-quota-empty"><q-icon name="playlist_add" /><strong>尚未选择定额</strong><span>从左侧选择后点击“添加”</span></div></div></div>
        <footer><span>候选 {{ filteredQuotas.length }} 条 · 已选 {{ quotaPickerSelections.length }} 条</span><button type="button" class="secondary" @click="showQuotaPicker=false">取消</button><button type="button" class="primary" @click="confirmQuotaPicker">确认添加</button></footer>
      </section>
    </q-dialog>
    <q-dialog v-model="showAiConfig">
      <form class="ai-config-modal" @submit.prevent="saveAiConfig">
        <header><div><span>AI MODEL SETTINGS</span><h2>AI 配置中心</h2><p>配置模块2用于字段识别和定额语义匹配的大模型</p></div><button type="button" @click="showAiConfig=false"><q-icon name="close" /></button></header>
        <div class="config-state" :class="{ online: aiStatus.enabled }"><q-icon :name="aiStatus.enabled ? 'check_circle' : 'info'" /><div><strong>{{ aiStatus.enabled ? 'AI大模型已启用' : '当前使用本地规则降级' }}</strong><span>{{ aiStatus.enabled ? aiStatus.model : '填写并测试配置后即可启用AI+定额双驱动' }}</span></div></div>
        <label class="switch-row"><input v-model="aiForm.enabled" type="checkbox"><span><strong>启用AI智能解析</strong><small>关闭后保留配置，但测算只使用本地规则和定额库</small></span></label>
        <div class="config-fields">
          <label><span>模型名称</span><input :value="selectedAiModel" readonly><small>请通过主界面 AI 解析引擎旁的“+”选择模型</small></label>
          <label><span>API密钥</span><div class="secret-input"><input v-model="aiForm.apiKey" :type="showApiKey ? 'text' : 'password'" :placeholder="aiStatus.hasApiKey ? '已保存；留空表示不修改' : '请输入API Key'"><button type="button" @click="showApiKey=!showApiKey"><q-icon :name="showApiKey ? 'visibility_off' : 'visibility'" /></button></div><small>密钥在服务器端加密保存，页面不会回显原密钥</small></label>
          <label><span>请求超时（秒）</span><input v-model.number="aiForm.timeout" type="number" min="10" max="120"></label>
          <label><span>单次AI复核上限</span><input v-model.number="aiForm.matchLimit" type="number" min="0" max="500"><small>编码精确匹配不消耗AI调用</small></label>
        </div>
        <p v-if="configMessage" class="config-message" :class="configMessageType">{{ configMessage }}</p>
        <footer><button class="secondary" type="button" :disabled="testingConfig || savingConfig" @click="testAiConfig"><q-icon name="network_check" />{{ testingConfig ? '正在测试…' : '测试连接' }}</button><span></span><button class="secondary" type="button" @click="showAiConfig=false">取消</button><button class="primary" type="submit" :disabled="savingConfig || testingConfig"><q-icon name="save" />{{ savingConfig ? '正在保存…' : '保存配置' }}</button></footer>
      </form>
    </q-dialog>
    <q-dialog v-model="showModelPicker">
      <section class="model-picker-modal">
        <header><div><span>AI MODEL LIBRARY</span><h2>选择大语言模型</h2><p>模型清单来源于交融 MaaS 服务，单击一行选择模型。</p></div><button type="button" @click="showModelPicker=false"><q-icon name="close" /></button></header>
        <div class="model-table-wrap"><table><thead><tr><th>选择</th><th>模型名称</th><th>参数量</th><th>上下文</th><th>支持深度思考</th></tr></thead><tbody><tr v-for="model in aiModels" :key="model.value" :class="{ selected: modelDraft === model.value }" @click="modelDraft=model.value"><td><input v-model="modelDraft" type="radio" name="ai-model" :value="model.value" :aria-label="`选择${model.label}`"></td><td><strong>{{ model.label }}</strong></td><td>{{ model.parameters }}</td><td>{{ model.context }}</td><td>{{ model.deepThinking ? '是' : '否' }}</td></tr></tbody></table></div>
        <footer><span>当前选择：<b>{{ modelDraft }}</b></span><button type="button" class="secondary" @click="showModelPicker=false">取消</button><button type="button" class="primary" :disabled="!modelDraft" @click="confirmModelPicker">确认选择</button></footer>
      </section>
