</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
type SummaryKey='labour'|'material'|'machine'|'management'|'profit'|'tax'|'total'|'matched'|'review';
interface FieldMapping{standardField:string;standardLabel:string;sourceHeader:string;column:number;confidence:number;method:string}
interface ParsingSheet{sourceName:string;headerRow:number;mappings:FieldMapping[];unmappedHeaders:string[]}
interface CostItem{sourceRow:number;sourceSheet:string;name:string;features:string;unit:string;quantity:number;quantityRecognized:boolean;rawFields:Record<string,string>;reviewReasons:string[];matchMethod:string;aiReason:string;listCode:string;listName:string;quotaCode:string;quotaName:string;quotaSelections?:CatalogQuota[];confidence:number;status:string;unitLabour:number;unitMaterial:number;unitMachine:number;subtotal:number}
interface AIState{enabled:boolean;mode:string;provider:string;model:string;calls:number;failures:number;errors:string[]}
interface AIConfigPublic{enabled:boolean;configured:boolean;hasApiKey:boolean;baseUrl:string;provider:string;model:string;timeout:number;matchLimit:number;fallback:string}
interface CostResult{source:string;catalog:{lists:number;quotas:number};ai:AIState;parsing:{sheets:ParsingSheet[];mappedFields:number;lowConfidenceFields:number;warnings:string[]};items:CostItem[];summary:Record<SummaryKey,number>;quotes:{breakEven:number;regular:number;competitive:number};sensitivity:{change:number;total:number}[];limitations:string}
interface CatalogList{code:string;name:string;unit:string}
interface CatalogQuota{code:string;name:string;unit:string;chapter:string;unitLabour:number;unitMaterial:number;unitMachine:number}
const professions=['建筑工程','安装工程','市政工程','矿山工程','园林绿化工程'];
const form=reactive({profession:'建筑工程',taxMode:'一般计税',manageRate:15,profitRate:10,taxRate:9,province:'山东省'});
