async function postAiConfig(path:string){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(aiForm)});const payload=await response.json() as {success?:boolean;message?:string}&Partial<AIConfigPublic>;if(!response.ok||!payload.success)throw new Error(payload.message||'操作失败');return payload}
async function changeAiModel(){aiForm.model=selectedAiModel.value;if(!aiStatus.configured){openAiConfig();return}savingConfig.value=true;try{Object.assign(aiForm,{enabled:aiStatus.enabled,baseUrl:aiStatus.baseUrl,model:selectedAiModel.value,apiKey:'',timeout:aiStatus.timeout,matchLimit:aiStatus.matchLimit});const payload=await postAiConfig('/api/cost/ai-config');Object.assign(aiStatus,payload)}catch{selectedAiModel.value=aiStatus.model||'jiaorong-kimi-k2.6'}finally{savingConfig.value=false}}
async function testAiConfig(){testingConfig.value=true;configMessage.value='';aiForm.model=selectedAiModel.value;try{const payload=await postAiConfig('/api/cost/ai-config/test');configMessage.value=payload.message||'连接成功';configMessageType.value='success'}catch(e){configMessage.value=e instanceof Error?e.message:'连接测试失败';configMessageType.value='error'}finally{testingConfig.value=false}}
async function saveAiConfig(){savingConfig.value=true;configMessage.value='';aiForm.model=selectedAiModel.value;try{const payload=await postAiConfig('/api/cost/ai-config');Object.assign(aiStatus,payload);aiForm.apiKey='';configMessage.value='配置已保存，下一次测算立即生效';configMessageType.value='success'}catch(e){configMessage.value=e instanceof Error?e.message:'配置保存失败';configMessageType.value='error'}finally{savingConfig.value=false}}
function selectFile(e:Event){selectedFile.value=(e.target as HTMLInputElement).files?.[0]||null;result.value=null;errorMessage.value=''}
function handleProvinceChange(){result.value=null;errorMessage.value=form.province==='山东省'?'':`${form.province}清单定额库待补充，当前暂不能进行测算`}
function formatBytes(n:number){return n>=1048576?`${(n/1048576).toFixed(2)} MB`:`${(n/1024).toFixed(1)} KB`}
function money(n?:number){return n==null?'—':Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}
function encode(file:File){return new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve((typeof r.result==='string'?r.result:'').split(',')[1]||'');r.onerror=()=>reject(new Error('文件读取失败'));r.readAsDataURL(file)})}
async function analyze(){if(!selectedFile.value)return;if(form.province!=='山东省'){errorMessage.value=`${form.province}清单定额库待补充，当前暂不能进行测算`;return}if(selectedFile.value.size>10485760){errorMessage.value='文件超过10MB，请拆分后上传';return}analyzing.value=true;errorMessage.value='';Object.assign(progress,{percent:2,stage:'准备任务',detail:'正在读取并上传清单文件'});try{const response=await fetch('/api/cost/analyze-stream',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/x-ndjson'},body:JSON.stringify({...form,fileName:selectedFile.value.name,fileBase64:await encode(selectedFile.value)})});const contentType=response.headers.get('content-type')||'';if(contentType.includes('text/html'))throw new Error('后台服务仍是旧版本，请停止当前服务并重新运行 npm run serve:lan');if(!response.ok||!response.body)throw new Error('无法启动成本测算任务');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',completed=false;while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split(/\r?\n/);buffer=lines.pop()||'';for(const line of lines){if(!line.trim())continue;let message:{type:string;percent?:number;stage?:string;detail?:string;data?:CostResult;message?:string};try{message=JSON.parse(line) as typeof message}catch{throw new Error('后台返回的数据格式不正确，请重新启动软件服务后再试')}if(message.type==='progress')Object.assign(progress,{percent:message.percent??progress.percent,stage:message.stage||progress.stage,detail:message.detail||''});else if(message.type==='result'&&message.data){result.value=message.data;Object.assign(progress,{percent:100,stage:'测算完成',detail:`已完成 ${message.data.items.length} 条清单的匹配与计价`});completed=true}else if(message.type==='error')throw new Error(message.message||'成本测算失败')}if(done)break}if(!completed)throw new Error('测算任务未返回结果')}catch(e){errorMessage.value=e instanceof Error?e.message:'成本测算失败';result.value=null}finally{analyzing.value=false}}
function barHeight(value:number){if(!result.value)return 0;const a=result.value.sensitivity.map(x=>x.total),min=Math.min(...a)*.96,max=Math.max(...a);return 20+(value-min)/Math.max(1,max-min)*75}
function cloneItem(item:CostItem):CostItem{return JSON.parse(JSON.stringify(item)) as CostItem}
function filterCatalog<T extends {code:string;name:string;chapter?:string}>(entries:T[],query:string){const keyword=query.trim().toLowerCase();if(!keyword)return entries;return entries.filter(entry=>`${entry.code} ${entry.name} ${entry.chapter||''}`.toLowerCase().includes(keyword))}
function hydrateSelectedQuotas(){if(!editItem.value)return;if(editItem.value.quotaSelections?.length){selectedQuotas.value=editItem.value.quotaSelections.map(entry=>({...entry}));return}selectedQuotas.value=editItem.value.quotaCode.split('；').map(code=>catalogQuotas.value.find(entry=>entry.code===code.trim())).filter((entry):entry is CatalogQuota=>Boolean(entry));if(!selectedQuotas.value.length&&editItem.value.quotaCode){selectedQuotas.value=[{code:editItem.value.quotaCode,name:editItem.value.quotaName,unit:editItem.value.unit,chapter:'',unitLabour:editItem.value.unitLabour,unitMaterial:editItem.value.unitMaterial,unitMachine:editItem.value.unitMachine}]}}
async function loadCatalog(){if(catalogLists.value.length||catalogLoading.value){hydrateSelectedQuotas();return}catalogLoading.value=true;try{const response=await fetch('/api/cost/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'catalog',profession:form.profession,taxMode:form.taxMode})});const payload=await response.json() as {success?:boolean;data?:{lists:CatalogList[];quotas:CatalogQuota[]};message?:string};if(!response.ok||!payload.success||!payload.data)throw new Error(payload.message||'清单库加载失败');catalogLists.value=payload.data.lists;catalogQuotas.value=payload.data.quotas;hydrateSelectedQuotas()}catch(e){editError.value=e instanceof Error?e.message:'清单库加载失败'}finally{catalogLoading.value=false}}
function openItemEditor(item:CostItem,index:number){editItem.value=cloneItem(item);editItemIndex.value=index;editReviewReasons.value=item.reviewReasons.join('\n');editError.value='';listSearch.value='';quotaSearch.value='';selectedQuotas.value=[];quotaCandidateCodes.value=[];quotaRemoveCodes.value=[];showItemEditor.value=true;void loadCatalog()}
function openListPicker(){listPickerCode.value=editItem.value?.listCode||'';listSearch.value='';showListPicker.value=true}
function confirmListPicker(){if(!editItem.value||!listPickerCode.value)return;const entry=catalogLists.value.find(item=>item.code===listPickerCode.value);if(!entry)return;editItem.value.listCode=entry.code;editItem.value.listName=entry.name;if(!editItem.value.unit&&entry.unit)editItem.value.unit=entry.unit;showListPicker.value=false}
function openQuotaPicker(){quotaPickerSelections.value=selectedQuotas.value.map(entry=>({...entry}));quotaCandidateCodes.value=[];quotaRemoveCodes.value=[];quotaSearch.value='';showQuotaPicker.value=true}
function addPickerQuotas(){for(const code of quotaCandidateCodes.value){const entry=catalogQuotas.value.find(item=>item.code===code);if(entry&&!quotaPickerSelections.value.some(item=>item.code===code))quotaPickerSelections.value.push({...entry})}quotaCandidateCodes.value=[]}
function toggleQuotaRemoval(code:string){quotaRemoveCodes.value=quotaRemoveCodes.value.includes(code)?quotaRemoveCodes.value.filter(item=>item!==code):[...quotaRemoveCodes.value,code]}
function removePickerQuotas(){quotaPickerSelections.value=quotaPickerSelections.value.filter(entry=>!quotaRemoveCodes.value.includes(entry.code));quotaRemoveCodes.value=[]}
function confirmQuotaPicker(){selectedQuotas.value=quotaPickerSelections.value.map(entry=>({...entry}));showQuotaPicker.value=false}
function recalculateResult(){if(!result.value)return;const summary=result.value.summary;summary.labour=result.value.items.reduce((s,i)=>s+Number(i.unitLabour||0)*Number(i.quantity||0),0);summary.material=result.value.items.reduce((s,i)=>s+Number(i.unitMaterial||0)*Number(i.quantity||0),0);summary.machine=result.value.items.reduce((s,i)=>s+Number(i.unitMachine||0)*Number(i.quantity||0),0);summary.management=(summary.labour+summary.material+summary.machine)*form.manageRate/100;summary.profit=(summary.labour+summary.material+summary.machine+summary.management)*form.profitRate/100;summary.tax=(summary.labour+summary.material+summary.machine+summary.management+summary.profit)*form.taxRate/100;summary.total=summary.labour+summary.material+summary.machine+summary.management+summary.profit+summary.tax;summary.matched=result.value.items.filter(i=>i.status==='已匹配').length;summary.review=result.value.items.length-summary.matched;result.value.quotes={breakEven:summary.total,regular:summary.total*1.05,competitive:summary.total*1.02}}
function saveItemEdit(){if(!result.value||!editItem.value||editItemIndex.value<0)return;if(selectedQuotas.value.length){editItem.value.quotaSelections=selectedQuotas.value.map(entry=>({...entry}));editItem.value.quotaCode=selectedQuotas.value.map(entry=>entry.code).join('；');editItem.value.quotaName=selectedQuotas.value.map(entry=>entry.name).join('；');editItem.value.unitLabour=selectedQuotas.value.reduce((sum,entry)=>sum+Number(entry.unitLabour||0),0);editItem.value.unitMaterial=selectedQuotas.value.reduce((sum,entry)=>sum+Number(entry.unitMaterial||0),0);editItem.value.unitMachine=selectedQuotas.value.reduce((sum,entry)=>sum+Number(entry.unitMachine||0),0)}else{editItem.value.quotaSelections=[];editItem.value.quotaCode='';editItem.value.quotaName='';editItem.value.unitLabour=0;editItem.value.unitMaterial=0;editItem.value.unitMachine=0}editItem.value.quantityRecognized=Number.isFinite(Number(editItem.value.quantity));editItem.value.subtotal=(Number(editItem.value.unitLabour||0)+Number(editItem.value.unitMaterial||0)+Number(editItem.value.unitMachine||0))*Number(editItem.value.quantity||0);result.value.items.splice(editItemIndex.value,1,cloneItem(editItem.value));recalculateResult();showItemEditor.value=false}
async function exportReport(){if(!result.value||exporting.value)return;exporting.value=true;errorMessage.value='';try{const response=await fetch('/api/cost/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({result:result.value,manageRate:form.manageRate,profitRate:form.profitRate,taxRate:form.taxRate})});if(!response.ok){let message='报表生成失败';try{const payload=await response.json() as {message?:string};message=payload.message||message}catch{/* 响应可能不是 JSON */}throw new Error(message)}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=`工程量清单与计价表-${new Date().toISOString().slice(0,10)}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){errorMessage.value=e instanceof Error?e.message:'报表生成失败'}finally{exporting.value=false}}
</script>

